<?php
require_once 'check_auth.php';
require_once '../config/database.php';
require_once '../config/payment_logger.php';
ensure_payment_log_schema($conn);

$q = trim((string)($_GET['q'] ?? ''));
$action = trim((string)($_GET['action'] ?? 'all'));
$where = ['1=1'];
if ($q !== '') {
    $safe = $conn->real_escape_string($q);
    $where[] = "(transaction_id LIKE '%$safe%' OR payment_id LIKE '%$safe%' OR user_id LIKE '%$safe%' OR customer_name LIKE '%$safe%' OR actor_id LIKE '%$safe%' OR actor_name LIKE '%$safe%')";
}
if (in_array($action, ['submitted','verified','rejected'], true)) $where[] = "action='".$conn->real_escape_string($action)."'";
$logs = $conn->query('SELECT * FROM payment_audit_logs WHERE '.implode(' AND ', $where).' ORDER BY created_at DESC,id DESC LIMIT 500');
$stats = $conn->query("SELECT COUNT(*) total,SUM(action='submitted') submitted,SUM(action='verified') verified,SUM(action='rejected') rejected FROM payment_audit_logs");
$summary = $stats ? $stats->fetch_assoc() : [];
function pl_h($value): string { return htmlspecialchars((string)$value, ENT_QUOTES, 'UTF-8'); }
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Payment Logs — HydroMIS</title><link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css" rel="stylesheet"><style>
:root{--bg:#0d1117;--card:#161b24;--soft:#1e2533;--line:rgba(255,255,255,.09);--text:#e8edf5;--muted:#8492a6;--aqua:#2dd4bf;--green:#22c55e;--red:#f43f5e;--blue:#3b82f6}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px 'Segoe UI',sans-serif}.top{display:flex;align-items:center;justify-content:space-between;padding:18px 28px;border-bottom:1px solid var(--line);background:var(--card)}.top a{color:var(--aqua);text-decoration:none}.page{padding:28px}.heading h1{margin:0;font-size:28px}.heading p{color:var(--muted)}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:22px 0}.stat,.panel,.filters{border:1px solid var(--line);border-radius:16px;background:var(--card)}.stat{padding:18px}.stat span{color:var(--muted);font-size:11px;text-transform:uppercase}.stat strong{display:block;margin-top:8px;font-size:26px}.filters{display:flex;gap:10px;padding:14px;margin-bottom:16px}.filters input,.filters select{min-height:42px;padding:0 12px;border:1px solid var(--line);border-radius:10px;background:var(--soft);color:var(--text)}.filters input{flex:1}.filters button{padding:0 18px;border:0;border-radius:10px;background:var(--aqua);font-weight:700}.panel{overflow:auto}table{width:100%;border-collapse:collapse;min-width:1100px}th,td{padding:13px 14px;text-align:left;border-bottom:1px solid var(--line);vertical-align:top}th{color:var(--muted);font-size:10px;text-transform:uppercase;background:var(--soft)}td{font-size:12px}.identity strong,.identity span{display:block}.identity span,.sub{margin-top:3px;color:var(--muted);font-size:10px}.badge{display:inline-block;padding:5px 8px;border-radius:99px;background:rgba(59,130,246,.13);color:var(--blue);font-size:10px;font-weight:800;text-transform:uppercase}.badge.verified{background:rgba(34,197,94,.13);color:var(--green)}.badge.rejected{background:rgba(244,63,94,.13);color:var(--red)}.empty{padding:50px;text-align:center;color:var(--muted)}@media(max-width:760px){.page{padding:16px}.stats{grid-template-columns:1fr 1fr}.filters{flex-direction:column}}
</style></head><body><header class="top"><a href="dashboard.php"><i class="fas fa-arrow-left"></i> Admin Dashboard</a><strong>HydroMIS Payment Audit</strong></header><main class="page"><div class="heading"><h1>Payment Logs</h1><p>Separate, traceable history showing who paid and who processed every payment action.</p></div><section class="stats"><div class="stat"><span>All events</span><strong><?= (int)($summary['total']??0) ?></strong></div><div class="stat"><span>Submitted</span><strong><?= (int)($summary['submitted']??0) ?></strong></div><div class="stat"><span>Verified</span><strong><?= (int)($summary['verified']??0) ?></strong></div><div class="stat"><span>Rejected</span><strong><?= (int)($summary['rejected']??0) ?></strong></div></section><form class="filters"><input name="q" value="<?=pl_h($q)?>" placeholder="Search customer, user ID, order, payment, or processor"><select name="action"><option value="all">All actions</option><?php foreach(['submitted','verified','rejected'] as $option):?><option value="<?=$option?>" <?=$action===$option?'selected':''?>><?=ucfirst($option)?></option><?php endforeach?></select><button><i class="fas fa-search"></i> Search</button></form><section class="panel"><table><thead><tr><th>Date</th><th>Customer / Payer</th><th>Order & Payment</th><th>Method</th><th>Amount</th><th>Action</th><th>Processed By</th><th>Status Change</th></tr></thead><tbody><?php if($logs&&$logs->num_rows):while($row=$logs->fetch_assoc()):?><tr><td><?=pl_h(date('M j, Y g:i A',strtotime($row['created_at'])))?></td><td class="identity"><strong><?=pl_h($row['customer_name']?:'Unknown customer')?></strong><span>User ID: <?=pl_h($row['user_id']?:'Not available')?></span></td><td class="identity"><strong>Order <?=pl_h($row['transaction_id'])?></strong><span><?=pl_h($row['payment_id']?:'No payment ID')?></span></td><td><?=pl_h(strtoupper((string)$row['payment_method']))?></td><td><strong>PHP <?=number_format((float)$row['amount'],2)?></strong></td><td><span class="badge <?=pl_h($row['action'])?>"><?=pl_h($row['action'])?></span><div class="sub"><?=pl_h($row['notes'])?></div></td><td class="identity"><strong><?=pl_h($row['actor_name']?:'System')?></strong><span><?=pl_h(ucfirst($row['actor_role']))?> · <?=pl_h($row['actor_id']?:'Automatic')?></span></td><td><?=pl_h(ucfirst((string)($row['old_status']?:'none')))?> → <strong><?=pl_h(ucfirst($row['new_status']))?></strong></td></tr><?php endwhile;else:?><tr><td colspan="8" class="empty">No payment events recorded yet. New submissions, verifications, and rejections will appear here.</td></tr><?php endif?></tbody></table></section></main></body></html>
